INSERT INTO equipos(id_equipo,marca,modelo,categoria,pais_marca,pais_fabricacion,anio_modelo,publicado,web_url,ficha_pdf_url,imagen_url,descripcion) VALUES ('GNSS-EMLID-RS4','Emlid','Reach RS4','GNSS','Hungría','Pendiente de confirmar',2025,TRUE,'https://emlid.com/reachrs4/','/media/emlid-rs4/ficha-tecnica-2026.pdf','/media/emlid-rs4/portada-horizontal.png','Receptor GNSS RTK base y rover de 672 canales con IMU, 16 GB internos, LTE nano-SIM y radio integrada LoRa/UHF Tx/Rx de hasta 2 W. Sin cámaras; modelo estándar, distinto del RS4 Pro.') ON CONFLICT(id_equipo) DO NOTHING;
INSERT INTO base_evaluacion(id_equipo,tiene_imu,imu_sin_limite_angular,imu_generacion,imu_tecnologia,tiene_camara,cantidad_camaras,mp_camara,laser,canales_gnss,memoria,memoria_es_interna,autonomia_bateria,bateria_interna,tipo_bateria,cantidad_baterias,peso_max,tiempo_inicializacion,rtk_horizontal_mm,rtk_vertical_mm,rtk_ppm_h,rtk_ppm_v,static_horizontal_mm,static_vertical_mm,static_ppm_h,static_ppm_v,largo_mm,ancho_mm,alto_mm,gps,glonass,galileo,beidou,qzss,navic_irnss,constelaciones,actualizacion_hz,temperatura_operacion_min_c,temperatura_operacion_max_c,proteccion_ip,usb,usb_c,carga_usb_c,rs232,bluetooth,bluetooth_version,wifi,wifi_estandar,lte_4g,sim_4g,sim_fisica,conectividad_nota,uhf_tx_rx_integrada,uhf_modo,radio_frecuencia,radio_potencia_max_w,radio_potencia_ajustable,protocolo_multimarca,radio_protocolos,registro_rinex,registro_rinex_3,rinex_3_directo,registro_propietario,formato_propietario,rinex_versiones,rinex_3_conversion,rinex_conversion_software,rinex_conversion_nota,ambiental_fuente,ambiental_notas,tecnica_fuente,tecnica_notas,baterias_conectores_fuente,baterias_conectores_notas,auditoria_fuente,auditoria_notas) VALUES ('GNSS-EMLID-RS4',TRUE,TRUE,'Segunda generación del algoritmo de compensación (no generación universal del sensor)','IMU calibrada de fábrica, sin magnetómetro. Inicialización de IMU de 7-10 s con FIX; precisión de inclinación RTK + 2 mm + 0.3 mm/grado. No confundir con tiempo de fijación GNSS.',FALSE,0,0,FALSE,672,16,TRUE,16,TRUE,'Li-ion interna 5000 mAh, 7.2 V, 36 Wh; carga USB-C PD.',1,927,5,7,14,1,1,4,8,0.5,1,128.6,128.6,99.3,TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,6,10,-40,65,'IP68',TRUE,TRUE,TRUE,TRUE,TRUE,'5.1 BR/EDR + LE',TRUE,'802.11 a/b/g/n',TRUE,TRUE,TRUE,'Módem LTE integrado con nano-SIM física; fallback 3G/2G. USB-C para carga PD y datos; Wi-Fi y Bluetooth 5.1. Verificar bandas y servicio celular de la oferta.',TRUE,'LoRa y UHF integradas Tx/Rx; base y rover','UHF 410-470 MHz; LoRa 863-870 / 902-928 MHz según región y antena',2,TRUE,TRUE,'UHF: TRIMTALK 450S, GMSK; LoRa: protocolo propietario Emlid. Potencias/frecuencias dependen de región, antena y configuración; no atribuir otros protocolos UHF.',TRUE,TRUE,TRUE,TRUE,'UBX (binario u-blox; no formato propietario Emlid)','Registro directo RINEX 3.03 documentado; conversión Emlid Studio 1.10 a 3.04. No se presume RINEX 2.x ni todas las revisiones 3.x.',TRUE,'Emlid Studio','Manual RS4/RS4 Pro: RINEX directo y respaldo UBX. Studio 1.10 añade L5 y conversión 3.04; comprobar firmware, archivos y versión. No confundir conversión con registro directo de toda versión.','RS4 datasheet (LoRa & UHF) 2026.pdf, p.2, Mechanical; manual oficial Reach RS4/RS4 Pro.','Operación -40 a +65 °C, IP68. No se declaran en esta ficha límites de almacenamiento, ensayo de caída, humedad o MIL-STD; quedan pendientes.','RS4 datasheet (LoRa & UHF) 2026.pdf pp.2-3; manual oficial docs.emlid.com/reachrs4; auditoría 2026-10-22.','RTK 7/14 mm +1 ppm. Estático 4 mm+0.5 ppm H y 8 mm+1 ppm V. PPK 5 mm+0.5 ppm H y 10 mm+1 ppm V, sin confundirlo con estático. Fijación GNSS ~5 s típica; IMU 7-10 s. Salida GNSS hasta 10 Hz, no 20 Hz por inferencia. RS4 estándar sin cámaras ni láser; no es RS4 Pro.','Ficha RS4 2026 p.2; manual oficial Specifications, puertos USB-C y RS-232.','16 h como rover RTK con inclinación y 22 h de registro; se puntúan 16 h RTK. USB-C PD: 5/9/12/15 V a 3 A. No asumir baterías de repuesto, reemplazo en caliente o elementos incluidos en el kit.','/media/emlid-rs4/ficha-tecnica-2026.pdf; https://emlid.com/reachrs4/','Alta del RS4 estándar; radio LoRa/UHF regional, app de campo Emlid Flow y oficina Emlid Studio. Modelo presentado en octubre de 2025; ficha aportada 2026. País de fabricación pendiente de etiqueta/certificado. Campos no publicados permanecen pendientes.') ON CONFLICT(id_equipo) DO NOTHING;
