INSERT INTO equipo_dato_fuentes(id_equipo,campo,valor_declarado,fuente_url,documento,version_fuente,estado,nota) VALUES ('GNSS-EMLID-RS4','tecnica_notas','RTK 7/14 mm +1 ppm. Estático 4 mm+0.5 ppm H y 8 mm+1 ppm V. PPK 5 mm+0.5 ppm H y 10 mm+1 ppm V, sin confundirlo con estático. Fijación GNSS ~5 s típica; IMU 7-10 s. Salida GNSS hasta 10 Hz, no 20 Hz por inferencia. RS4 estándar sin cámaras ni láser; no es RS4 Pro.','/media/emlid-rs4/ficha-tecnica-2026.pdf','RS4 datasheet (LoRa & UHF) 2026; manual específico RS4','rs4-auditoria-2026-10-22','confirmado','Ficha RS4 estándar pp.2-3 y documentación específica del fabricante; no mezclar RS4 Pro.') ON CONFLICT(id_equipo,campo,fuente_url,version_fuente) DO NOTHING;
