INSERT INTO equipo_dato_fuentes(id_equipo,campo,valor_declarado,fuente_url,documento,version_fuente,estado,nota) SELECT e.id_equipo,'imu_sin_limite_angular','Pendiente de confirmar',COALESCE(e.web_url,''),'Declaración específica de ausencia de límite angular','rs4-auditoria-2026-10-22','no_verificado','No se deduce de una IMU genérica ni de su generación.' FROM equipos e JOIN base_evaluacion b USING(id_equipo) WHERE e.publicado AND e.categoria='GNSS' AND e.id_equipo<>'GNSS-EMLID-RS4' ON CONFLICT(id_equipo,campo,fuente_url,version_fuente) DO NOTHING;
